def sphereDiskInverseAmbient (n : ℕ) (z : EuclideanSpace ℝ (Fin (n + 1))) :
    EuclideanSpace ℝ (Fin n) :=
  (2 * Real.sqrt ((1 - z 0) / 2))⁻¹ • sphereTail n z

